type Loaded<T> =
  | { status: "ok"; value: T }
  | { status: "degraded"; value: T; reason: string };
async function report(id: string): Promise<Loaded<Report>> {
  try { return { status: "ok", value: await backend.report(id) }; }
  catch (e: unknown) {                       // unknown, not any
    metrics.degraded(e);
    return { status: "degraded", value: await cache.report(id), reason: String(e) };
  }
}
